import React, { useState, useEffect } from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  useLocation,
  useNavigate
} from 'react-router-dom';

// AUTH
import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

// LAYOUTS
import Dashboard from './components/DashboardLayout';
import ClientLayout from './components/ClientLayout';

// CLIENT PAGES
import Home from './components/Clients/Home/Home';
import Services from './components/Clients/Services/Services';
import Portfolio from './components/Clients/Portfolio/Portfolio';
import Contact from './components/Clients/Contact/Contact';

// Fonction pour nettoyer le token
const cleanToken = (token) => {
  if (!token) return null;

  let cleanToken = token.trim();

  // Enlever les guillemets
  if (cleanToken.startsWith('"') && cleanToken.endsWith('"')) {
    cleanToken = cleanToken.slice(1, -1);
  }
  if (cleanToken.startsWith("'") && cleanToken.endsWith("'")) {
    cleanToken = cleanToken.slice(1, -1);
  }

  // Vérifier que c'est un JWT
  const parts = cleanToken.split('.');
  if (parts.length !== 3) {
    console.error('Token invalide:', cleanToken.substring(0, 50) + '...');
    return null;
  }

  return cleanToken;
};

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [currentUser, setCurrentUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const location = useLocation();
  const navigate = useNavigate();

  // Vérifier session au chargement
  useEffect(() => {
    const checkAuth = async () => {
      const authToken = localStorage.getItem('authToken');
      const userData = localStorage.getItem('userData');

      console.log('🔍 Vérification auth au démarrage...');
      console.log('- Token présent:', !!authToken);
      console.log('- UserData présent:', !!userData);

      if (authToken && userData) {
        try {
          // Nettoyer le token
          const cleanTokenValue = cleanToken(authToken);

          if (!cleanTokenValue) {
            console.log('❌ Token invalide, déconnexion...');
            handleLogout();
            setIsLoading(false);
            return;
          }

          // Mettre à jour le token nettoyé
          if (cleanTokenValue !== authToken) {
            localStorage.setItem('authToken', cleanTokenValue);
          }

          // Parser userData
          const user = JSON.parse(userData);
          console.log('✅ Utilisateur trouvé:', user.email);

          // Vérifier le token avec l'API
          try {
            const response = await fetch('http://localhost:5000/api/auth/profile', {
              method: 'GET',
              headers: {
                'Authorization': `Bearer ${cleanTokenValue}`,
                'Content-Type': 'application/json'
              }
            });

            if (response.ok) {
              const profileData = await response.json();
              console.log('✅ Token validé par API');

              setCurrentUser({
                ...user,
                email: user.email || '',
                first_name: user.first_name || user.name || user.email?.split('@')[0] || 'Utilisateur',
                role: user.role || 'user'
              });
              setUserRole(user.role || 'user');
              setIsAuthenticated(true);

              // Redirection selon rôle
              const shouldRedirectToAdmin = user.role === 'admin' && !location.pathname.startsWith('/admin');
              const shouldRedirectFromAdmin = user.role !== 'admin' && location.pathname.startsWith('/admin');

              if (shouldRedirectToAdmin) {
                navigate('/admin', { replace: true });
              } else if (shouldRedirectFromAdmin) {
                navigate('/', { replace: true });
              }
            } else {
              console.warn('Token invalide, déconnexion...');
              handleLogout();
            }
          } catch (apiError) {
            console.error('Erreur vérification API:', apiError);
            // On garde l'utilisateur connecté même si l'API échoue (pour offline)
            setCurrentUser(user);
            setUserRole(user.role || 'user');
            setIsAuthenticated(true);
          }

        } catch (error) {
          console.error('Erreur parsing userData:', error);
          handleLogout();
        }
      }

      setIsLoading(false);
    };

    checkAuth();
  }, [location.pathname, navigate]);

  const handleLogin = (userData, token) => {
    console.log('🔑 Login callback appelé');

    // Nettoyer le token
    const cleanTokenValue = cleanToken(token);

    if (!cleanTokenValue) {
      console.error('Token invalide reçu dans handleLogin');
      return;
    }

    // Formatage des données utilisateur
    const formattedUser = {
      ...userData,
      email: userData.email || '',
      first_name: userData.first_name || userData.name || userData.email?.split('@')[0] || 'Utilisateur',
      role: userData.role || 'user'
    };

    console.log('💾 Stockage des données:', formattedUser.email);

    // Stocker les données
    localStorage.setItem('userData', JSON.stringify(formattedUser));
    localStorage.setItem('authToken', cleanTokenValue);

    // Mettre à jour l'état
    setCurrentUser(formattedUser);
    setUserRole(formattedUser.role);
    setIsAuthenticated(true);

    console.log('✅ Utilisateur connecté:', formattedUser.email);

    // Redirection
    if (formattedUser.role === 'admin') {
      navigate('/admin', { replace: true });
    } else {
      navigate('/', { replace: true });
    }
  };

  const handleLogout = () => {
    console.log('🚪 Déconnexion...');
    localStorage.removeItem('userData');
    localStorage.removeItem('authToken');
    localStorage.removeItem('userRole');
    localStorage.removeItem('userEmail');
    setCurrentUser(null);
    setIsAuthenticated(false);
    setUserRole(null);
    navigate('/login', { replace: true });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  return (
    <Routes>
      {/* LOGIN */}
      <Route
        path="/login"
        element={
          isAuthenticated ? (
            userRole === 'admin' ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />
          ) : (
            <ClientLayout 
              isAuthenticated={isAuthenticated} 
              onLogout={handleLogout} 
              currentUser={currentUser}
            >
              <Login onLogin={handleLogin} />
            </ClientLayout>
          )
        }
      />

      {/* REGISTER */}
      <Route
        path="/register"
        element={
          isAuthenticated ? (
            userRole === 'admin' ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />
          ) : (
            <ClientLayout 
              isAuthenticated={isAuthenticated} 
              onLogout={handleLogout} 
              currentUser={currentUser}
            >
              <Register onLogin={handleLogin} />
            </ClientLayout>
          )
        }
      />

      {/* DASHBOARD ADMIN */}
      <Route
        path="/admin/*"
        element={
          <ProtectedRoute 
            isAuthenticated={isAuthenticated} 
            requiredRole="admin" 
            userRole={userRole}
          >
            <Dashboard 
              onLogout={handleLogout} 
              currentUser={currentUser} 
            />
          </ProtectedRoute>
        }
      />

      {/* ROUTES CLIENT PUBLIQUES */}
      <Route
        path="/*"
        element={
          <ClientLayout 
            isAuthenticated={isAuthenticated} 
            onLogout={handleLogout} 
            currentUser={currentUser}
          >
            <Routes>
              <Route path="/" element={<Home currentUser={currentUser} />} />
              <Route path="/services" element={<Services />} />
              <Route path="/portfolio" element={<Portfolio />} />
              <Route path="/contact" element={<Contact />} />
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </ClientLayout>
        }
      />
    </Routes>
  );
}

export default function AppWrapper() {
  return (
    <Router>
      <App />
    </Router>
  );
}
